CREATE TABLE public.career_positions (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT NOT NULL UNIQUE,
 name_vi TEXT NOT NULL, name_en TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN ('software','data_ai','security','infrastructure','quality','product')),
 description TEXT NOT NULL DEFAULT '', skills TEXT[] NOT NULL DEFAULT '{}', search_text TEXT NOT NULL,
 version UUID NOT NULL DEFAULT gen_random_uuid(), deleted_at TIMESTAMPTZ,
 created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX career_positions_names ON public.career_positions(lower(name_vi),lower(name_en)) WHERE deleted_at IS NULL;
ALTER TABLE public.student_profiles ADD COLUMN career_position_id UUID REFERENCES public.career_positions(id);
CREATE INDEX student_profiles_career_position ON public.student_profiles(career_position_id);
ALTER TABLE public.career_positions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.career_positions FROM PUBLIC;
DO $$ DECLARE r TEXT; BEGIN
 FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
  IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN EXECUTE format('REVOKE ALL ON public.career_positions FROM %I',r); END IF;
 END LOOP;
END $$;
-- Initial catalog is inserted once by this migration; deleted entries are not recreated on startup.
